input.command:
d=$(mktemp -d) && mkdir -p $d/pash_annotations/annotation_generation/annotation_generators && touch $d/pash_annotations/__init__.py $d/pash_annotations/annotation_generation/__init__.py $d/pash_annotations/annotation_generation/annotation_generators/__init__.py
cat > $d/pash_annotations/annotation_generation/annotation_generators/InputOutputInfoGenerator_Interface.py <<'EOF'
class InputOutputInfoGeneratorInterface:
    def __init__(self, flags, nops): self.flags, self.nops, self.calls = flags, nops, []
    def does_flag_option_list_contain_at_least_one_of(self, l): return any(f in self.flags for f in l)
    def __getattr__(self, n):
        def f(*a): self.calls.append(n)
        return f
EOF
cat > $d/pash_annotations/annotation_generation/annotation_generators/ParallelizabilityInfoGenerator_Interface.py <<'EOF'
class ParallelizabilityInfoGeneratorInterface:
    def __init__(self): self.calls = []
    def __getattr__(self, n):
        def f(*a): self.calls.append(n)
        return f
EOF
PYTHONPATH=$d:output/annotation python3 -c "
from InputOutputInfoGeneratorSha256sum import InputOutputInfoGeneratorSha256sum as IO
from ParallelizabilityInfoGeneratorSha256sum import ParallelizabilityInfoGeneratorSha256sum as P
for flags in ([], ['-c'], ['-c','--status'], ['-b','--tag']):
    g = IO(flags, 2); g.generate_info(); print(flags, g.calls)
p = P(); p.generate_info(); print('par', p.calls)"
